arguments.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "breakfast",
                Description = "Fluffy buttermilk pancakes perfect for a weekend morning.",
                Ingredients = ["2 cups flour", "2 tbsp sugar", "1 tbsp baking powder", "1/2 tsp salt", "2 eggs", "1 3/4 cups milk", "1/4 cup melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and butter together.", "Combine wet and dry ingredients until just blended.", "Pour 1/4 cup batter onto a hot griddle.", "Cook until bubbles form, then flip and cook until golden."],
                TotalRatings = 12, RatingSum = 50
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "breakfast",
                Description = "Simple, healthy, and endlessly customizable avocado toast.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper", "Red pepper flakes"],
                Steps = ["Toast the bread until golden and crispy.", "Mash avocado with lemon juice, salt, and pepper.", "Spread the avocado mixture on toast.", "Top with red pepper flakes and serve."],
                TotalRatings = 8, RatingSum = 35
            },
            new Recipe
            {
                Id = 3, Title = "Caesar Salad Wrap", Category = "lunch",
                Description = "All the flavors of a Caesar salad wrapped up for easy eating.",
                Ingredients = ["2 large flour tortillas", "2 cups chopped romaine", "1/2 cup Caesar dressing", "1/4 cup parmesan", "1 cup croutons", "Grilled chicken (optional)"],
                Steps = ["Toss romaine with Caesar dressing and parmesan.", "Add croutons and grilled chicken if using.", "Divide filling between tortillas.", "Roll tightly and cut in half."],
                TotalRatings = 6, RatingSum = 25
            },
            new Recipe
            {
                Id = 4, Title = "Tomato Basil Soup", Category = "lunch",
                Description = "A comforting bowl of creamy tomato soup with fresh basil.",
                Ingredients = ["2 cans crushed tomatoes", "1 cup vegetable broth", "1/2 cup heavy cream", "1/4 cup fresh basil", "2 cloves garlic", "1 onion", "2 tbsp olive oil"],
                Steps = ["Sauté onion and garlic in olive oil until soft.", "Add crushed tomatoes and broth; simmer 20 minutes.", "Blend until smooth with an immersion blender.", "Stir in cream and chopped basil.", "Season to taste and serve warm."],
                TotalRatings = 10, RatingSum = 43
            },
            new Recipe
            {
                Id = 5, Title = "Lemon Herb Roasted Chicken", Category = "dinner",
                Description = "Juicy roasted chicken with bright lemon and fresh herbs.",
                Ingredients = ["1 whole chicken (4 lbs)", "2 lemons", "4 cloves garlic", "Fresh rosemary and thyme", "3 tbsp olive oil", "Salt and pepper"],
                Steps = ["Preheat oven to 425°F (220°C).", "Pat chicken dry and season inside and out.", "Stuff cavity with lemon halves, garlic, and herbs.", "Rub skin with olive oil, salt, and pepper.", "Roast for 1 hour 15 minutes until juices run clear.", "Rest 10 minutes before carving."],
                TotalRatings = 15, RatingSum = 68
            },
            new Recipe
            {
                Id = 6, Title = "Spaghetti Carbonara", Category = "dinner",
                Description = "Authentic Italian carbonara with eggs, cheese, and pancetta.",
                Ingredients = ["1 lb spaghetti", "6 oz pancetta", "4 egg yolks", "1 cup pecorino romano", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted water until al dente.", "Crisp pancetta in a skillet over medium heat.", "Whisk egg yolks with grated pecorino and pepper.", "Toss hot pasta with pancetta and rendered fat.", "Remove from heat; stir in egg mixture quickly.", "Serve immediately with extra cheese."],
                TotalRatings = 20, RatingSum = 92
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Lava Cake", Category = "desserts",
                Description = "Rich individual chocolate cakes with a molten center.",
                Ingredients = ["4 oz dark chocolate", "1/2 cup butter", "2 eggs", "2 egg yolks", "1/4 cup sugar", "2 tbsp flour"],
                Steps = ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar until thick.", "Fold in chocolate mixture and flour.", "Pour into greased ramekins.", "Bake 12–14 minutes until edges are set but center jiggles.", "Invert onto plates and serve immediately."],
                TotalRatings = 18, RatingSum = 85
            },
            new Recipe
            {
                Id = 8, Title = "Strawberry Shortcake", Category = "desserts",
                Description = "Light, fluffy biscuits topped with sweet strawberries and cream.",
                Ingredients = ["2 cups flour", "1/3 cup sugar", "1 tbsp baking powder", "6 tbsp cold butter", "3/4 cup milk", "1 lb strawberries", "Whipped cream"],
                Steps = ["Mix flour, sugar, baking powder; cut in butter.", "Stir in milk until dough just comes together.", "Pat dough out and cut into rounds.", "Bake at 400°F (200°C) for 15 minutes.", "Slice strawberries and toss with a little sugar.", "Split biscuits; layer with berries and whipped cream."],
                TotalRatings = 9, RatingSum = 38
            }
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        ["breakfast", "lunch", "dinner", "desserts"];

    public string GetCategoryDisplayName(string category) => category switch
    {
        "breakfast" => "Breakfast",
        "lunch" => "Lunch",
        "dinner" => "Dinner",
        "desserts" => "Desserts",
        _ => category
    };

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
