        ← Back to @RecipeService.GetCategoryDisplayName(recipe.Category)
    </a>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded bg-light d-inline-block">
    <span class="me-2 fw-bold">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                title="@star star(s)"
                @onclick="() => SubmitRating(star)"
                disabled="@hasRated">
            @(star <= (hoverStar ?? selectedStar) ? "★" : "☆")
        </button>
    }

    @if (hasRated)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }

    <div class="small text-muted mt-1">
        @if (TotalRatings > 0 || hasRated)
        {
            <span>⭐ @displayAverage.ToString("F1") avg — @displayTotal rating(s)</span>
        }
        else
        {
            <span>No ratings yet — be the first!</span>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int selectedStar;
    private int? hoverStar;
    private bool hasRated;
    private double displayAverage;
    private int displayTotal;

    protected override void OnParametersSet()
    {
        displayAverage = CurrentAverage;
        displayTotal = TotalRatings;
    }

    private void SubmitRating(int stars)
    {
        if (hasRated) return;

        RecipeService.AddRating(RecipeId, stars);
        selectedStar = stars;
        hasRated = true;

        var updated = RecipeService.GetRecipeById(RecipeId);
        if (updated is not null)
        {
            displayAverage = updated.AverageRating;
            displayTotal = updated.TotalRatings;
        }
    }
}

