@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@using System.ComponentModel.DataAnnotations
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@submittedTitle</strong>" has been added.
        <a href="recipe/@submittedId">View it here</a>.
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" class="mt-3" style="max-width: 700px;">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label class="form-label fw-bold">Recipe Title</label>
            <InputText @bind-Value="Model!.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
            <ValidationMessage For="() => Model!.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Category</label>
            <InputSelect @bind-Value="Model!.Category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="Breakfast">Breakfast</option>
                <option value="Lunch">Lunch</option>
                <option value="Dinner">Dinner</option>
                <option value="Desserts">Desserts</option>
            </InputSelect>
            <ValidationMessage For="() => Model!.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Ingredients</label>
            <InputTextArea @bind-Value="Model!.Ingredients" class="form-control" rows="5"
                           placeholder="One ingredient per line&#10;e.g.&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => Model!.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold">Steps</label>
            <InputTextArea @bind-Value="Model!.Steps" class="form-control" rows="5"
                           placeholder="One step per line&#10;e.g.&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => Model!.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success" disabled="@isSubmitting">
            @(isSubmitting ? "Submitting..." : "Submit Recipe")
        </button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    private SubmissionModel? Model { get; set; }
    private bool submitted;
    private bool isSubmitting;
    private string submittedTitle = string.Empty;
    private int submittedId;

    protected override void OnInitialized() => Model ??= new();

    private void HandleSubmit()
    {
        isSubmitting = true;
        try
        {
            var submission = new RecipeSubmission
            {
                Title = Model!.Title,
                Category = Model.Category,
                Ingredients = Model.Ingredients,
                Steps = Model.Steps
            };

            var recipe = RecipeService.AddRecipe(submission);
            submittedTitle = recipe.Title;
            submittedId = recipe.Id;
            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private class SubmissionModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3–100 characters.")]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

